manifest:
{
  "id": "com.example.hello",
  "version": "1.0.0",
  "name": "Hello Circle",
  "description": "A tiny signed sample plugin that adds a circle.",
  "publisher": "Example Co.",
  "engines": { "sketchor": "^0.3.0" },
  "main": "plugin.js",
  "contributes": {
    "commands": [{ "id": "hello.circle", "title": "Hello: add a circle" }]
  },
  "permissions": ["read-document", "write-document"]
}

code:
// Self-contained plugin: no imports; uses only the injected `sketchor` client.
export default {
  activate(sketchor) {
    sketchor.commands.register("hello.circle", () => {
      const id = "hp" + Date.now().toString(36) + Math.floor(Math.random() * 1e6).toString(36);
      sketchor.document.apply([
        { type: "add-entity", entity: { id, type: "circle", center: { x: 0, y: 0 }, radius: 15 } },
      ]);
      sketchor.ui.notify("Hello Circle added a circle");
    });
  },
};
